#!/usr/bin/env python3
"""
Todo App with Todo model, Category model, TodoManager with filtering, sorting, and JSON persistence
"""

import json
import os
from datetime import datetime
from typing import List, Optional, Dict, Any
from enum import Enum


class Status(Enum):
    PENDING = "pending"
    COMPLETED = "completed"


class Category:
    """Category model for organizing todos"""

    def __init__(self, name: str, description: str = ""):
        self.name = name
        self.description = description

    def to_dict(self) -> Dict[str, Any]:
        return {
            "name": self.name,
            "description": self.description
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'Category':
        return cls(data["name"], data["description"])

    def __str__(self) -> str:
        return f"Category(name='{self.name}', description='{self.description}')"


class Todo:
    """Todo model with title, description, completion status, and category"""

    def __init__(self, title: str, description: str = "", category: Optional[Category] = None, status: Status = Status.PENDING):
        self.title = title
        self.description = description
        self.category = category
        self.status = status
        self.created_at = datetime.now()
        self.updated_at = datetime.now()

    def to_dict(self) -> Dict[str, Any]:
        return {
            "title": self.title,
            "description": self.description,
            "category": self.category.to_dict() if self.category else None,
            "status": self.status.value,
            "created_at": self.created_at.isoformat(),
            "updated_at": self.updated_at.isoformat()
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'Todo':
        category = Category.from_dict(data["category"]) if data["category"] else None
        todo = cls(data["title"], data["description"], category, Status(data["status"]))
        todo.created_at = datetime.fromisoformat(data["created_at"])
        todo.updated_at = datetime.fromisoformat(data["updated_at"])
        return todo

    def mark_completed(self):
        """Mark the todo as completed"""
        self.status = Status.COMPLETED
        self.updated_at = datetime.now()

    def mark_pending(self):
        """Mark the todo as pending"""
        self.status = Status.PENDING
        self.updated_at = datetime.now()

    def __str__(self) -> str:
        status_str = "✓" if self.status == Status.COMPLETED else "○"
        return f"{status_str} {self.title} ({self.category.name if self.category else 'No Category'})"


class TodoManager:
    """Manager for todos with filtering, sorting, and JSON persistence"""

    def __init__(self, data_file: str = "todos.json"):
        self.data_file = data_file
        self.todos: List[Todo] = []
        self.categories: List[Category] = []
        self.load_data()

    def add_todo(self, todo: Todo) -> None:
        """Add a new todo to the manager"""
        self.todos.append(todo)
        self.save_data()

    def remove_todo(self, title: str) -> bool:
        """Remove a todo by title"""
        for i, todo in enumerate(self.todos):
            if todo.title == title:
                del self.todos[i]
                self.save_data()
                return True
        return False

    def get_todo(self, title: str) -> Optional[Todo]:
        """Get a todo by title"""
        for todo in self.todos:
            if todo.title == title:
                return todo
        return None

    def get_todos(self) -> List[Todo]:
        """Get all todos"""
        return self.todos.copy()

    def filter_by_status(self, status: Status) -> List[Todo]:
        """Filter todos by status"""
        return [todo for todo in self.todos if todo.status == status]

    def filter_by_category(self, category_name: str) -> List[Todo]:
        """Filter todos by category name"""
        return [todo for todo in self.todos if todo.category and todo.category.name == category_name]

    def sort_by_status(self) -> List[Todo]:
        """Sort todos by status (completed first)"""
        return sorted(self.todos, key=lambda x: x.status.value == "completed", reverse=True)

    def sort_by_date(self, reverse: bool = False) -> List[Todo]:
        """Sort todos by creation date"""
        return sorted(self.todos, key=lambda x: x.created_at, reverse=reverse)

    def sort_by_title(self, reverse: bool = False) -> List[Todo]:
        """Sort todos by title"""
        return sorted(self.todos, key=lambda x: x.title.lower(), reverse=reverse)

    def add_category(self, category: Category) -> None:
        """Add a new category"""
        self.categories.append(category)
        self.save_data()

    def get_category(self, name: str) -> Optional[Category]:
        """Get a category by name"""
        for category in self.categories:
            if category.name == name:
                return category
        return None

    def save_data(self) -> None:
        """Save todos and categories to JSON file"""
        data = {
            "todos": [todo.to_dict() for todo in self.todos],
            "categories": [category.to_dict() for category in self.categories]
        }
        with open(self.data_file, 'w') as f:
            json.dump(data, f, indent=2)

    def load_data(self) -> None:
        """Load todos and categories from JSON file"""
        if not os.path.exists(self.data_file):
            return

        try:
            with open(self.data_file, 'r') as f:
                data = json.load(f)

            self.todos = [Todo.from_dict(todo_data) for todo_data in data.get("todos", [])]
            self.categories = [Category.from_dict(category_data) for category_data in data.get("categories", [])]
        except (json.JSONDecodeError, KeyError):
            # If file is corrupted, start fresh
            self.todos = []
            self.categories = []


def main():
    """Example usage of the todo app"""
    # Create a todo manager
    manager = TodoManager()

    # Create some categories
    work_category = Category("Work", "Work-related tasks")
    personal_category = Category("Personal", "Personal tasks")

    manager.add_category(work_category)
    manager.add_category(personal_category)

    # Create some todos
    todo1 = Todo("Complete project proposal", "Write and submit the project proposal", work_category)
    todo2 = Todo("Buy groceries", "Purchase items for the week", personal_category)
    todo3 = Todo("Call mom", "Check in with mom", personal_category)

    # Add todos to manager
    manager.add_todo(todo1)
    manager.add_todo(todo2)
    manager.add_todo(todo3)

    # Display all todos
    print("All todos:")
    for todo in manager.get_todos():
        print(f"  {todo}")

    # Filter by status
    print("\nCompleted todos:")
    for todo in manager.filter_by_status(Status.COMPLETED):
        print(f"  {todo}")

    # Filter by category
    print("\nWork todos:")
    for todo in manager.filter_by_category("Work"):
        print(f"  {todo}")

    # Sort todos
    print("\nTodos sorted by title:")
    for todo in manager.sort_by_title():
        print(f"  {todo}")

    # Mark a todo as completed
    todo1.mark_completed()
    manager.save_data()

    print("\nAfter marking first todo as completed:")
    for todo in manager.get_todos():
        print(f"  {todo}")


if __name__ == "__main__":
    main()
